    interface Checked{void run()throws Exception;}
    static void verify(boolean b,String m){assertions++;if(!b)throw new AssertionError(m);}
    static void reject(String code,Checked f)throws Exception{try{f.run();throw new AssertionError("Expected "+code);}catch(NativePlacementEdits.Fault e){verify(code.equals(e.code),"Expected "+code+", got "+e.code+": "+e.getMessage());refusals++;}}
