        boolean revoked,failBefore,failAfter,failFence;String mode="normal";int reservations,invalidations,callbacks;NativePlacementEdits.Publication retained;
        Guard(Job job,String name)throws Exception{
            owned=job;file=evidence.resolve(name+".jsonl");ledger=new NativeJobLineage((type,payload)->record(type,payload));ledger.createFresh(jobId,"canonical-simulator");
            loads=new NativeBoardLoads((type,payload)->{record(type,payload);ledger.observe(type,payload);});loads.bindJob(job,jobId,true);
        }
        void record(String type,Map<String,Object> payload)throws Exception{NativePlacementStructureTest.force(file,JSON.toJson(Bridge.map("type",type,"payload",payload)));}
        public synchronized NativePlacementEdits.StructureState requireUnexecuted(Configuration c,Job j)throws Exception{
            if(c!=config||j!=owned||revoked)throw new NativePlacementEdits.Fault("STRUCTURE_AUTHORITY_STALE","Test authority lost");
            NativeJobLineage.Snapshot s;try{s=ledger.requirePristine(jobId,permit);}catch(NativeJobLineage.Fault f){throw new NativePlacementEdits.Fault(f.code,f.getMessage());}
            loads.publishSnapshot();for(Object raw:(List<?>)loads.snapshot().get("loads")){Map<?,?> l=(Map<?,?>)raw;if(((Number)l.get("native_history_entries")).intValue()!=0)throw new NativePlacementEdits.Fault("LINEAGE_HISTORY_PRESENT","Retained native keys");}
            return new NativePlacementEdits.StructureState(s.lineageId,s.revision,s.reservedLogicalIds);
        }
        public synchronized void reserveAndForce(NativePlacementEdits.StructureState expected,JsonObject reservation)throws Exception{
            verify(expected.same(requireUnexecuted(config,owned)),"Exact reservation prestate");if(failBefore)throw new java.io.IOException("before force");List<String> keys=new ArrayList<>();for(JsonElement e:reservation.getAsJsonArray("logical_ids"))keys.add(e.getAsString());
            permit=ledger.reserve(jobId,expected.revision,reservation.get("transaction_id").getAsString(),reservation.get("source_fingerprint").getAsString(),keys);reservations++;if(failAfter)throw new java.io.IOException("after force");
        }
        public synchronized void invalidateBeforePublication(Job j,List<String> roots)throws Exception{verify(reservations==1,"Reservation before invalidation");invalidations++;if(failFence)throw new java.io.IOException("invalidation");loads.invalidateRegistration("cfg-1","model-panel");NativeBoardLoads.invalidateTransforms(j);}
        public synchronized void publishIfCurrent(Configuration c,Job j,NativePlacementEdits.StructureState expected,NativePlacementEdits.Publication publication)throws Exception{
            callbacks++;retained=publication;if(mode.equals("noop"))return;if(mode.equals("revoke"))revoked=true;if(mode.equals("change"))placement(j,"solo","R1").getDefinition().setRank(901);
            if(mode.equals("thread")){Thread t=new Thread(()->{try{publication.publish();}catch(Exception accepted){}});t.start();t.join();return;}
            verify(expected.same(requireUnexecuted(c,j)),"Commit callback owns exact current authority");publication.publish();
            if(mode.equals("repeat")){try{publication.publish();}catch(Exception suppressed){}}
        }
        void complete(Map<String,Object> result)throws Exception{loads.jobChanged(owned,jobId);ledger.publicationSucceeded(jobId,((Number)result.get("lineage_revision")).longValue(),(String)result.get("transaction_id"),(String)NativePlacementEdits.inspect(config,owned,0,1).get("source_fingerprint"));permit.close();permit=null;reservations=0;}
        NativeJobLineage replay()throws Exception{NativeJobLineage copy=new NativeJobLineage((t,p)->{throw new AssertionError("replay is read-only");});for(String line:Files.readAllLines(file)){Map<String,Object> row=NativeJournalJson.parseObject(line);copy.observe((String)row.get("type"),(Map<String,Object>)row.get("payload"));}return copy;}
